"""AWS Lambda release profile: the deploy, health and rollback commands for a Lambda function released through aliases, generated by code from a small profile the
release owner writes. A model never writes these commands. Plain code: it validates the profile, builds the commands and checks the account before anything runs.
Profile (JSON): {"service": "lambda", "account_id": "123456789012", "region": "eu-west-1", "function": "orders-api", "alias": "live", "previous_alias": "previous",
                 "package": "dist/app.zip" | {"s3_bucket": "...", "s3_key": "..."}, "alarm": "optional CloudWatch alarm name", "smoke_payload": "optional JSON the function may be invoked with"}
The `alias` and `previous_alias` aliases must already exist. A release records the version `alias` points to in `previous_alias`, publishes the new code, moves `alias` to it,
and a rollback moves `alias` back to `previous_alias`. Nothing here reads or stores credentials: the aws CLI uses whatever session the machine already has.
"""
import json
import re

NAME = re.compile(r"[A-Za-z0-9_-]{1,64}")
PATH = re.compile(r"[\w./-]{1,200}")
BUCKET = re.compile(r"[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]")
REGION = re.compile(r"[a-z]{2}(-[a-z]+)+-\d")
ACCOUNT = re.compile(r"\d{12}")
FIELDS = ("service", "account_id", "region", "function", "alias", "previous_alias", "package")
FREE = re.compile(r"[^A-Za-z0-9 ._-]")


def validate(p):
    """Why the profile cannot be used, as a list of sentences (empty when it can)."""
    if not isinstance(p, dict):
        return ["the AWS profile must be a JSON object"]
    bad = []
    if p.get("service") != "lambda":
        bad.append("service must be 'lambda' (the only AWS service supported so far)")
    if not ACCOUNT.fullmatch(str(p.get("account_id", ""))):
        bad.append("account_id must be the 12-digit AWS account id the release is allowed to touch")
    if not REGION.fullmatch(str(p.get("region", ""))):
        bad.append("region must look like eu-west-1")
    for k in ("function", "alias", "previous_alias"):
        if not NAME.fullmatch(str(p.get(k, ""))):
            bad.append(f"{k} must be 1 to 64 letters, digits, - or _")
    if p.get("alias") and p.get("alias") == p.get("previous_alias"):
        bad.append("alias and previous_alias must be different aliases")
    pk = p.get("package")
    if isinstance(pk, str):
        if not PATH.fullmatch(pk) or not pk.endswith(".zip"):
            bad.append("package must be a relative .zip path without spaces or quotes")
    elif isinstance(pk, dict):
        if not BUCKET.fullmatch(str(pk.get("s3_bucket", ""))) or not PATH.fullmatch(str(pk.get("s3_key", ""))):
            bad.append("package.s3_bucket and package.s3_key must be a plain bucket name and key")
    else:
        bad.append("package is needed: a .zip path, or {s3_bucket, s3_key}")
    if p.get("alarm") and not NAME.fullmatch(str(p["alarm"])):
        bad.append("alarm must be a plain alarm name (letters, digits, - or _)")
    if p.get("smoke_payload") not in (None, ""):
        try:
            json.loads(p["smoke_payload"] if isinstance(p["smoke_payload"], str) else json.dumps(p["smoke_payload"]))
        except ValueError:
            bad.append("smoke_payload must be valid JSON")
        if "'" in (p["smoke_payload"] if isinstance(p["smoke_payload"], str) else json.dumps(p["smoke_payload"])):
            bad.append("smoke_payload must not contain a single quote")
    return bad


def _cli(p, *parts):
    return "aws lambda " + " ".join(parts) + f" --region {p['region']}"


def _val(p, *parts, query, name=None):
    """A command substitution that prints one value; commands built from it stay self-contained, one process each."""
    return "$(" + _cli(p, *parts, f"--query '{query}'", "--output text") + ")"


def commands(p, version="", commit=""):
    """dict(promotion=[(purpose, command)], health=[(name, command, pass, pause, rollback)], rollback=[(purpose, command)]). Raises ValueError on a bad profile."""
    if bad := validate(p):
        raise ValueError("; ".join(bad))
    f, a, pa = p["function"], p["alias"], p["previous_alias"]
    note = FREE.sub("", f"release {version} {commit[:12]}").strip()[:200] or "release"
    newest = _val(p, "list-versions-by-function", f"--function-name {f}", query="Versions[-1].Version")
    live = _val(p, "get-alias", f"--function-name {f}", f"--name {a}", query="FunctionVersion")
    prev = _val(p, "get-alias", f"--function-name {f}", f"--name {pa}", query="FunctionVersion")
    pk = p["package"]
    code = _cli(p, "update-function-code", f"--function-name {f}", f"--zip-file fileb://{pk}" if isinstance(pk, str) else f"--s3-bucket {pk['s3_bucket']} --s3-key {pk['s3_key']}")
    promotion = [
        ("Check the account is the approved one", f'test "$(aws sts get-caller-identity --query Account --output text --region {p["region"]})" = "{p["account_id"]}"'),
        ("Check both aliases exist", _cli(p, "get-alias", f"--function-name {f}", f"--name {a}", "--query FunctionVersion --output text") + " && "
                                    + _cli(p, "get-alias", f"--function-name {f}", f"--name {pa}", "--query FunctionVersion --output text")),
        ("Upload the new code", code),
        ("Wait until the code update has finished", _cli(p, "wait function-updated", f"--function-name {f}")),
        ("Publish the new version", _cli(p, "publish-version", f"--function-name {f}", f'--description "{note}"')),
        ("Remember the version now live, for rollback (not if it is already the newest)", f'if test "{live}" = "{newest}"; then true; else '
                                                                                         + _cli(p, "update-alias", f"--function-name {f}", f"--name {pa}", f"--function-version {live}") + "; fi"),
        ("Move the live alias to the new version", _cli(p, "update-alias", f"--function-name {f}", f"--name {a}", f"--function-version {newest}")),
    ]
    health = [("alias points at the newest version", f'test "{_val(p, "get-alias", f"--function-name {f}", f"--name {a}", query="FunctionVersion")}" = "{newest}"', "exit 0", "1", "2"),
              ("last code update succeeded", f'test "{_val(p, "get-function-configuration", f"--function-name {f}", query="LastUpdateStatus")}" = "Successful"', "exit 0", "1", "2")]
    if p.get("alarm"):
        health.append(("CloudWatch alarm is OK", f'test "$(aws cloudwatch describe-alarms --alarm-names {p["alarm"]} --region {p["region"]} --query \'MetricAlarms[0].StateValue\' --output text)" = "OK"', "exit 0", "1", "2"))
    if p.get("smoke_payload") not in (None, ""):
        pay = p["smoke_payload"] if isinstance(p["smoke_payload"], str) else json.dumps(p["smoke_payload"])
        health.append(("smoke invocation returns 200", _cli(p, "invoke", f"--function-name {f}:{a}", f"--payload '{pay}'", "--cli-binary-format raw-in-base64-out", "--query StatusCode --output text /dev/null"),
                       "value == 200", "-", "1"))
    rollback = [("Move the live alias back to the previous version", _cli(p, "update-alias", f"--function-name {f}", f"--name {a}", f"--function-version {prev}"))]
    return dict(promotion=promotion, health=health, rollback=rollback)


def render(p, version="", commit=""):
    """The three plan sections (markdown) that replace whatever the model wrote for them."""
    c = commands(p, version, commit)
    t = lambda rows: "\n".join(f"| {i} | `{cmd}` | {why} |" for i, (why, cmd) in enumerate(rows, 1))
    return dict(**{
        "Promotion commands": "| Step | Command | Purpose |\n|---|---|---|\n" + t(c["promotion"]),
        "Health checks": "| Check | Command | Pass condition | Pause after | Roll back after |\n|---|---|---|---|---|\n"
                         + "\n".join(f"| {n} | `{cmd}` | {ok} | {ps} | {rb} |" for n, cmd, ok, ps, rb in c["health"]),
        "Rollback": "| Step | Command | Purpose |\n|---|---|---|\n" + t(c["rollback"])})


def replace_sections(plan, sections):
    for title, body in sections.items():
        plan, n = re.subn(rf"(?ms)^(## {re.escape(title)}\n).*?(?=^## |\Z)", lambda m: m.group(1) + body + "\n\n", plan, count=1)
        if not n:
            plan = plan.rstrip() + f"\n\n## {title}\n{body}\n"
    return plan


def expected_account(plan_commands):
    """The account id the approved plan's first command checks, so the guard cannot be changed after approval by editing a profile file."""
    m = re.search(r'= "(\d{12})"', plan_commands[0]) if plan_commands else None
    return m.group(1) if m else ""
